from fastapi import FastAPI, HTTPException, status
from pydantic import BaseModel, Field
from typing import List

app = FastAPI()

class ItemCreate(BaseModel):
    title: str = Field(..., min_length=1, max_length=80)

class ItemUpdate(BaseModel):
    done: bool

items = []
next_id = 1

@app.get('/api/items')
def get_items():
    return items

@app.post('/api/items')
def create_item(item: ItemCreate):
    global next_id
    item_dict = {
        'id': next_id,
        'title': item.title,
        'done': False
    }
    items.append(item_dict)
    next_id += 1
    return item_dict

@app.patch('/api/items/{id}')
def update_item(id: int, item: ItemUpdate):
    global items
    for i in range(len(items)):
        if items[i]['id'] == id:
            items[i]['done'] = item.done
            return items[i]
    raise HTTPException(status_code=404, detail="Item not found")

@app.delete('/api/items/{id}')
def delete_item(id: int):
    global items
    for i in range(len(items)):
        if items[i]['id'] == id:
            items.pop(i)
            return status.HTTP_204_NO_CONTENT
    raise HTTPException(status_code=404, detail="Item not found")

import { useState, useEffect } from 'react';

const App = () => {
  const [items, setItems] = useState([]);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch('api/items')
      .then(res => res.json())
      .then(data => {
        setItems(data);
        setLoading(false);
      })
      .catch(err => {
        setError('Failed to load items');
        setLoading(false);
      });
  }, []);

  const addItem = async (title) => {
    if (!title || title.trim() === '' || title.length > 80) {
      setError('Title must be 1-80 characters');
      return;
    }
    try {
      const res = await fetch('api/items', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title })
      });
      if (!res.ok) {
        throw new Error(await res.text());
      }
      const newItem = await res.json();
      setItems(prev => [...prev, newItem]);
    } catch (err) {
      setError(err.message);
    }
  };

  const toggleItem = async (id) => {
    try {
      const res = await fetch(`api/items/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ done: !items.find(i => i.id === id).done })
      });
      if (!res.ok) {
        throw new Error(await res.text());
      }
      const updatedItem = await res.json();
      setItems(prev => prev.map(item => 
        item.id === id ? updatedItem : item
      ));
    } catch (err) {
      setError(err.message);
    }
  };

  const deleteItem = async (id) => {
    try {
      const res = await fetch(`api/items/${id}`, {
        method: 'DELETE'
      });
      if (!res.ok) {
        throw new Error(await res.text());
      }
      setItems(prev => prev.filter(item => item.id !== id));
    } catch (err) {
      setError(err.message);
    }
  };

  return (
    <div className="main">
      <h1>Reading Room</h1>
      <form className="form" onSubmit={(e) => { e.preventDefault(); addItem(e.target[0].value); }}>
        <input
          type="text"
          data-testid="item-input"
          placeholder="Add a book title"
          className="input"
          required
        />
        <button
          type="submit"
          data-testid="add-item"
          className="button"
        >
          Add
        </button>
      </form>

      {loading ? (
        <p>Loading...</p>
      ) : (
        <ul>
          {items.map(item => (
            <li key={item.id} className={`item-row ${item.done ? 'done' : ''}`}>
              <input
                type="checkbox"
                data-testid="item-toggle"
                className="input"
                checked={item.done}
                onChange={() => toggleItem(item.id)}
              />
              <span>{item.title}</span>
              <button
                type="button"
                data-testid="item-delete"
                className="button"
                onClick={() => deleteItem(item.id)}
              >
                Delete
              </button>
            </li>
          ))}
          {error && <p className="error">{error}</p>}
        </ul>
      )}
    </div>
  );
};

export default App;

